308	  bool enabled_ = true;
309	  bool window_complete_ = false;
310	  uint64_t end_retired_ = 0;
311	  uint64_t total_cycles_ = 0;
312	  uint64_t start_cycle_ = 0;
313	  uint64_t recorded_insns_ = 0;
