17	/// In-order Kanata pipeline viewer — writes Konata-compatible pipeline logs.
18	template<typename CPU>
19	class KanataViewer : public PipelineViewer<CPU>
20	{
21	public:
22	  KanataViewer(CPU& cpu,
23	               std::unique_ptr<kanata::KanataLogger> logger,
24	               kanata::PipelineConfig config)
25	      : logger_(std::move(logger))
26	  {
27	    auto vpu_config = config.vpu;
28	    modeler_ = std::make_unique<kanata::PipelineModeler<CPU>>(
29	      cpu, *logger_, std::move(config));
30	
31	    if (vpu_config) {
32	      vpu_modeler_ = std::make_unique<kanata::VpuPipelineModeler<CPU>>(
33	        cpu, *logger_, *modeler_, *vpu_config);
34	      modeler_->set_vpu(vpu_modeler_.get());
35	    }
36	  }
37	
38	  void on_cycle() override
39	  {
40	    modeler_->record();
41	    logger_->advance_cycle(1);
42	  }
43	
44	  void close() override { logger_->flush_all(); }
45	
46	  bool wants_exit() const override { return logger_->window_complete(); }
47	
48	private:
49	  std::unique_ptr<kanata::KanataLogger> logger_;
50	  std::unique_ptr<kanata::PipelineModeler<CPU>> modeler_;
51	  std::unique_ptr<kanata::VpuPipelineModeler<CPU>> vpu_modeler_;
52	};
53	
54	/// OoO Kanata pipeline viewer — age-based tracking for AX66 (single core).
55	template<typename CPU>
56	class OoOKanataViewer : public PipelineViewer<CPU>
57	{
58	public:
59	  OoOKanataViewer(CPU& cpu,
60	                  std::unique_ptr<kanata::KanataLogger> logger,
61	                  OoOPipelineConfig config)
62	      : logger_(std::move(logger))
63	      , modeler_(cpu, *logger_, std::move(config))
64	  {}
65	
66	  void on_cycle() override
67	  {
68	    modeler_.record();
69	    logger_->advance_cycle(1);
70	  }
71	
72	  void close() override
73	  {
74	    modeler_.finalize();
75	    logger_->flush_all();
76	  }
77	
78	  bool wants_exit() const override { return logger_->window_complete(); }
79	
80	private:
81	  std::unique_ptr<kanata::KanataLogger> logger_;
82	  OoOPipelineModeler<CPU> modeler_;
83	};
84	
85	/// Multi-core OoO Kanata viewer — wraps N independent OoOKanataViewers.
86	template<typename CPU>
87	class MultiCoreOoOKanataViewer : public PipelineViewer<CPU>
88	{
89	public:
90	  void add(std::unique_ptr<OoOKanataViewer<CPU>> viewer)
91	  {
92	    viewers_.push_back(std::move(viewer));
93	  }
94	
95	  void on_cycle() override
96	  {
97	    for (auto& v : viewers_)
98	      v->on_cycle();
99	  }
100	
101	  void close() override
102	  {
103	    for (auto& v : viewers_)
104	      v->close();
105	  }
106	
107	  bool wants_exit() const override
108	  {
109	    for (auto const& v : viewers_)
110	      if (v->wants_exit())
111	        return true;
112	    return false;
113	  }
114	
115	private:
116	  std::vector<std::unique_ptr<OoOKanataViewer<CPU>>> viewers_;
117	};
118	
119	/// Factory: create a pipeline viewer (in-order or OoO) if the CPU is
120	/// supported. Returns nullptr if no pipeline config matches the CPU.
121	///
122	/// For multi-core OoO (AX66 with NDS_NHART > 1), splits the output into
123	/// per-core files: "output.kanata" -> "output_core0.kanata",
124	/// "output_core1.kanata".
125	template<typename CPU>
126	std::unique_ptr<PipelineViewer<CPU>> make_kanata_viewer(
127	  CPU& cpu, const std::string& filename,
128	  const std::string& objdump_file = "",
129	  std::optional<kanata::LoopGate> gate = std::nullopt)
130	{
131	  // Try OoO path first (AX66)
132	  if (kanata::is_ooo_cpu(cpu.modelName())) {
133	    int num_cores = kanata::ax66_ooo_num_cores(cpu);
134	    spdlog::info("Kanata: detected AX66 OoO pipeline ({} core{})",
135	                 num_cores, num_cores > 1 ? "s" : "");
136	
137	    if (num_cores == 1) {
138	      // Single-core: one file, unchanged behavior
139	      auto logger = std::make_unique<kanata::KanataLogger>(filename, gate);
140	      if (!logger->is_open())
141	        return nullptr;
142	      if (!objdump_file.empty())
143	        logger->load_objdump(objdump_file);
144	      auto config = kanata::make_ax66_ooo_config(cpu, 0);
145	      return std::make_unique<OoOKanataViewer<CPU>>(
146	        cpu, std::move(logger), std::move(config));
147	    }
148	
149	    // Multi-core: split into per-core files
150	    namespace fs = std::filesystem;
151	    auto path = fs::path(filename);
152	    auto stem = path.stem().string();
153	    auto ext = path.extension().string();
154	    auto parent = path.parent_path();
155	
156	    auto multi = std::make_unique<MultiCoreOoOKanataViewer<CPU>>();
157	    for (int core = 0; core < num_cores; ++core) {
158	      auto core_file =
159	        (parent / fmt::format("{}_core{}{}", stem, core, ext)).string();
160	      spdlog::info("Kanata: core {} -> {}", core, core_file);
161	      auto logger = std::make_unique<kanata::KanataLogger>(core_file, gate);
162	      if (!logger->is_open())
163	        return nullptr;
164	      if (!objdump_file.empty())
165	        logger->load_objdump(objdump_file);
166	      auto config = kanata::make_ax66_ooo_config(cpu, core);
167	      multi->add(std::make_unique<OoOKanataViewer<CPU>>(
168	        cpu, std::move(logger), std::move(config)));
169	    }
170	    return multi;
171	  }
172	
173	  // In-order path
174	  auto config = kanata::detect_config(cpu.modelName());
175	  if (!config)
176	    return nullptr;
177	
